#!/usr/bin/env python3
"""Build an additive, point-in-time NBA evidence audit; no external dependencies."""
import csv, html, json, math
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
E = lambda x: html.escape(str(x), quote=True)

def a(url, label):
    return f'<a href="{E(url)}">{E(label)}</a>'

def table(headers, rows):
    return '<div class="scroll"><table><thead><tr>' + ''.join(f'<th scope="col">{E(h)}</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{cell}</td>' for cell in row) + '</tr>' for row in rows) + '</tbody></table></div>'

def page(name, title, body):
    nav = [('index.html','Overview'),('results.html','Model review'),('correlations.html','Correlations'),('strategy.html','Strategies & gates'),('flagged.html','Flagged for review')]
    links = ''.join(f'<a {"aria-current=page" if name == path else ""} href="{path}">{label}</a>' for path,label in nav)
    doc = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Independent NBA evidence audit"><title>{E(title)} | NBA Evidence Audit</title><link rel="stylesheet" href="style.css"></head><body><header><div class="wrap"><a class="brand" href="index.html">OWN5 <span> / NBA EVIDENCE AUDIT</span></a><nav aria-label="Primary">{links}</nav></div></header><main class="wrap"><p class="eyebrow">INDEPENDENT REVIEW · 05 NOV 2026 UTC</p><h1>{E(title)}</h1>{body}</main><footer><div class="wrap">Research only. No bet recommendations or guarantees. <a href="../index.html">Own5 home</a> · <a href="../nba-signal-lab/index.html">Original NBA Signal Lab</a></div></footer></body></html>'''
    (HERE / name).write_text(doc, encoding='utf-8')

with (HERE/'results.csv').open(newline='', encoding='utf-8') as f:
    results = list(csv.DictReader(f))
outputs = json.loads((ROOT/'nba-signal-lab/data/outputs.json').read_text(encoding='utf-8'))
models = {(r['game_date'],r['away_team'],r['home_team']):r for r in outputs['model_lines']}
assert len(results)==6 and len(models)==6
joined=[]
for r in results:
    m=models[(r['date'],r['away'],r['home'])]
    actual=int(r['home_score'])-int(r['away_score'])
    total=int(r['home_score'])+int(r['away_score'])
    pred=float(m['model_home_spread']) # despite legacy key, this is expected HOME MARGIN
    joined.append((r,m,actual,total,pred))
margin_mae=sum(abs(pred-actual) for r,m,actual,total,pred in joined)/len(joined)
total_mae=sum(abs(float(m['model_total'])-total) for r,m,actual,total,pred in joined)/len(joined)
wins=sum((pred>0)==(actual>0) for r,m,actual,total,pred in joined if pred != 0 and actual != 0)
rows=[]
for r,m,margin,total,pred in joined:
    rows.append([E(r['away']+' @ '+r['home']), E(f'{r["away_score"]}–{r["home_score"]}'), E(f'{margin:+d}'), E(f'{pred:+.1f}'), E(f'{total}'), E(f'{m["model_total"]:.1f}'), a(r['source_url'],'NBA final')+' · '+a('../nba-signal-lab/model-lines.html','model')])
leaders='https://www.nba.com/stats/leaders?Season=2025-26'
games='https://www.nba.com/games?date=2026-11-04'
nist='https://www.itl.nist.gov/div898/handbook/eda/section3/eda35c.htm'
issues=[
 ('F01','High','Home-margin sign mismatch','The formula and raw JSON use positive for an expected home win. The original model page calls the same value a spread and says negative means home favorite. Read values as expected home margin; the conventional home spread is its negative. Do not place a bet from that label.',games,'../nba-signal-lab/model-lines.html'),
 ('F02','High','Parlay arithmetic reversed','The original executive summary says the independence product overstates the joint probability when observed lift exceeds one. For the same sample, joint = lift × product, so lift above one means the product understates the observed joint probability. No prospective edge follows.',leaders,'../research/nba-signal-lab/EXECUTIVE_SUMMARY.md'),
 ('F03','High','Independence is not established','A lag-one scoring correlation near zero or a confidence interval containing zero does not prove independence, especially for different players or games. Do not pass a parlay independence gate on that basis.',nist,'../nba-signal-lab/correlations.html'),
 ('F04','Medium','Selected players mischaracterized','The league leaders page lists Dončić first, Gilgeous-Alexander second, and Edwards third by points per game. The original summary calls Dončić and Edwards the top two. Two-player pooled estimates are not league-wide estimates.',leaders,'../research/nba-signal-lab/EXECUTIVE_SUMMARY.md'),
 ('F05','High','Odds and settlement missing','Verified historical prices, timestamped market lines, settlement rules, and graded bet ledger are absent in the reviewed lab. Accuracy against actual scores is not betting profit, CLV, or evidence of a positive expected return.',games,'../nba-signal-lab/model-lines.html'),
 ('F06','High','Not a full independent audit','The six final scores were checked individually against the NBA calendar. Original team and player input tables were not independently checked line by line in this review. Assertions and linked URLs do not by themselves verify source content.',leaders,'../nba-signal-lab/data-verified.html'),
 ('F07','Medium','Stale, partial slate','The reviewed model covers six games on November 4, not the full calendar; it is a historical snapshot, not current lines. The NBA calendar displayed 14 games for that date.',games,'../nba-signal-lab/model-lines.html'),
 ('F08','Medium','Shrinkage is not luck removal','A prior-weighted win rate is shrinkage, not the Deflated Sharpe Ratio and not proof that chance has been eliminated. Uncertainty, multiple comparisons, dependency and prices must be assessed separately.',nist,'../nba-signal-lab/luck-vs-skill.html'),
 ('F09','Medium','Pairwise phi is not a three-leg joint model','Pairwise associations alone do not uniquely determine a three-event joint probability. Empirical joint frequencies are exploratory, not a validated method for pricing future bets.',leaders,'../nba-signal-lab/correlations.html'),
 ('F10','Low','Live calendar inconsistency','On review the November 5 calendar displayed two games, while the game list said no games scheduled. Do not infer either matchups or a current slate from this inconsistent rendering.', 'https://www.nba.com/games?date=2026-11-05','../nba-signal-lab/flagged.html')]
issue_rows=[[E(i), E(sev), E(title), E(desc), a(src,'official source')+' · '+a(ref,'reviewed artifact')] for i,sev,title,desc,src,ref in issues]
page('index.html','NBA research, with evidence in view',f'''<p class="lede">An independent audit of an existing NBA line-originating lab. Six historical model projections are compared with official final scores; outstanding model and evidence concerns remain visible.</p><div class="cards"><div><b>6</b><span>historical games reviewed</span></div><div><b>0</b><span>strategies certified by this audit</span></div><div><b>{len(issues)}</b><span>review flags</span></div></div><div class="notice"><strong>Executive summary:</strong> the original lab has useful exploratory building blocks, but missing market prices and graded bets prevent any claim of betting skill or real rewards. Luck cannot be eliminated. Historical results and assumptions are not live recommendations.</div><h2>Start here</h2>{table(['Category','Finding','Official context'],[['Model review',f'{wins}/6 predicted winners; {margin_mae:.2f} point margin MAE; {total_mae:.2f} point total MAE. Six-game descriptive sample only. {a("results.html","See results →")}',a(games,'NBA scoreboard')],['Correlations','Eleven independently checked Edwards games; exploratory only. '+a('correlations.html','See sample →'),a(leaders,'NBA player data')],['Strategies','Singles, cross-game parlays and player-prop combos are proposed but all gates remain pending. '+a('strategy.html','See gates →'),a(leaders,'NBA player data')],['Flagged for review','Sign convention, independence claims, missing odds and source-audit limitations. '+a('flagged.html','See flags →'),a(nist,'NIST autocorrelation guidance')]])}<h2>Scope &amp; provenance</h2><p>This review independently checked six final scores and the NBA scoring-leaders order on 5 November. Model projections and pooled correlations are prior repository outputs, not official NBA values and not independently verified input by input. See the {a('flagged.html','review flags')} and {a('../nba-signal-lab/index.html','original research lab')} for context. This is not a full repository-wide verification.</p>''')
page('results.html','Historical model review',f'''<p class="lede">Six games from the existing 4 November snapshot, joined by date and teams to NBA final scores. This is a descriptive check, not a wagering backtest.</p><div class="notice">The existing JSON key <code>model_home_spread</code> is calculated as the expected <strong>home margin</strong>: positive favors the home team. A conventional home betting spread is its negative. The original page labels the sign inconsistently.</div><h2>Final scores and projections</h2><p>Score order is away–home. Actual margin is home minus away. Model values are derived research estimates, not official or market lines.</p>{table(['Away @ home','Final','Actual home margin','Model home margin','Actual total','Model total','Sources'],rows)}<h2>Descriptive diagnostics</h2>{table(['Measure','Result','Interpretation','Official results'],[['Winner direction',f'{wins}/6','Model margin sign versus actual margin; not ATS betting.',a(games,'NBA games')],['Margin MAE',f'{margin_mae:.2f} points','Mean absolute error across these six games.',a(games,'NBA games')],['Total MAE',f'{total_mae:.2f} points','Mean absolute error across these six games.',a(games,'NBA games')]])}<p>No market price, odds, stake, injury timestamp, or settlement record was verified, so ROI, CLV and certified strategy performance are blank. This sample was reviewed after the games and is too small to establish skill; original inputs were not independently fully reverified. Compute reproduced by <a href="build.py">build.py</a>; source scores in <a href="results.csv">results.csv</a>.</p>''')
strategies=[('Single game spread or total','Team-strength blend and availability-aware projected distributions.','Timestamped snapshots, correct sign, calibrated out-of-sample forecast and verified executable price.','Pending',games),('Cross-game parlay','Joint outcome modeling for chosen legs; avoid assuming independence from low lag-one scoring correlation.','Verified leg prices, joint calibration and settlement; hold out future games.','Pending',nist),('Same-player prop combo','Minutes and player-stat joint distribution, conditional on actual availability.','Verified prop thresholds and prices; player-specific holdout and directly modeled joint outcomes.','Pending',leaders)]
strategy_rows=[[E(x) for x in r[:4]]+[a(r[4],'official context')] for r in strategies]
gates=[('Source integrity','Original observations, timestamps, odds, and settlement independently checked.','Pending',games),('No leakage','Freeze code, parameters and decisions before event; retain timestamped input snapshots.','Pending',games),('Out-of-sample','Evaluate on future held-out games; avoid selection based on the evaluation set.','Pending',nist),('Probability & correlation','Assess calibration of marginal and joint probabilities; uncertainty and dependence are explicit.','Pending',nist),('Economic validation','Use actual available prices and settlement; compute net profit including fees and voids.','Blocked: no verified odds ledger',games),('Multiple testing & robustness','Predeclare the strategy family; correct selection effects, account for dependent observations and assess stability.','Pending',nist),('Reward eligibility','Only verified, independently audited results can qualify; funding and payout rules must be documented.','Blocked: no verified funding',games)]
gate_rows=[[E(x) for x in r[:3]]+[a(r[3],'official context')] for r in gates]
# Independently transcribed compact sample; every numeric input checked against the filtered NBA game log.
with (HERE/'edwards-sample.csv').open(newline='',encoding='utf-8') as f:
    sample=list(csv.DictReader(f))
assert len(sample)==11
sample_source='https://www.nba.com/stats/player/1630162/boxscores?Season=2025-26&DateFrom=2025-10-01&DateTo=2025-11-20'
def pearson(x,y):
    mx=sum(x)/len(x); my=sum(y)/len(y)
    return sum((a-mx)*(b-my) for a,b in zip(x,y))/math.sqrt(sum((a-mx)**2 for a in x)*sum((b-my)**2 for b in y))
pts=[int(r['points']) for r in sample]; ast=[int(r['assists']) for r in sample]; reb=[int(r['rebounds']) for r in sample]
a25=[int(v>=25) for v in pts]; b5=[int(v>=5) for v in ast]
joint=sum(a*b for a,b in zip(a25,b5))/len(sample); product=(sum(a25)/len(sample))*(sum(b5)/len(sample))
cor_rows=[[E('Points / assists'), E('11'), E(f'{pearson(pts,ast):.3f}'), E('Pearson r; per-game counts.'), a(sample_source,'NBA filtered game log')],
          [E('Points / rebounds'), E('11'), E(f'{pearson(pts,reb):.3f}'), E('Pearson r; per-game counts.'), a(sample_source,'NBA filtered game log')],
          [E('Points ≥25 / assists ≥5'), E('11'), E(f'{pearson(a25,b5):.3f}'), E(f'Binary phi; joint {joint:.3f}, product {product:.3f}.'), a(sample_source,'NBA filtered game log')]]
sample_rows=[[E(r['date']), E(r['points']), E(r['rebounds']), E(r['assists']), a(sample_source,'NBA game log')+' · '+a(r['source_url'],'game')] for r in sample]
page('correlations.html','Exploratory correlations',f'''<p class="lede">A deliberately narrow, independently checked example: Anthony Edwards' first 11 listed games of the 2025–26 regular season, from the official filtered NBA game log. These are in-sample arithmetic, not official NBA estimates or validated parlay prices.</p><div class="notice">Only 11 games, one player, and a nonrandom date window. Thresholds are illustrative choices made for this retrospective audit; no holdout, odds, uncertainty interval, or generalization is established. A near-zero correlation never proves independence.</div><h2>Computed measures</h2>{table(['Variables','Player-games','Coefficient','Interpretation','Official data'],cor_rows)}<p>Binary phi is Pearson correlation of two 0/1 indicators; the joint and product are empirical sample proportions. Pairwise correlation does not identify a three-leg joint probability. Player selection, rest, availability and game context can change the distribution.</p><h2>Verified sample inputs</h2>{table(['Date','Points','Rebounds','Assists','NBA source'],sample_rows)}<p>All 33 values were compared to the filtered league table and to the original lab's CSV. Formula and input: <a href="build.py">build.py</a> and <a href="edwards-sample.csv">edwards-sample.csv</a>. No unverified prices were filled in.</p>''')
page('strategy.html','Strategies, validation & leaderboard',f'''<p class="lede">Candidate research hypotheses, not certified betting systems. Official links provide data context, not validation of the model or the proposed gates.</p><h2>Strategy catalog</h2>{table(['Category','Signal proposal','Required evidence','Status','Source'],strategy_rows)}<h2>Fail-closed gates</h2>{table(['Gate','Requirement','Status','Source'],gate_rows)}<h2>Leaderboard and rewards</h2><p>No strategy has passed these gates in this review. No independently verified graded ledger or funded prize pool was found, so ranks, profit, prizes and rewards are intentionally blank. Compare strategies by out-of-sample net return and properly calibrated probabilities only after prices, selection rules, uncertainty and dependence are available. Luck cannot be removed; uncertainty can only be quantified under stated assumptions.</p><p>For the existing exploratory correlations and assumptions see the {a('../nba-signal-lab/correlations.html','original correlation page')} and {a('flagged.html','review flags')}; those coefficients are not validated prices.</p>''')
page('flagged.html','Flagged for review',f'''<p class="lede">Issues in the reviewed artifacts, with official sources for the underlying context and direct links to the affected work. These flags are not corrections to files owned by another session.</p>{table(['ID','Severity','Issue','Finding / safe interpretation','Sources'],issue_rows)}<p>Source pages are dynamic and can change. This review accessed them on 5 November 2026 UTC. Every row links to an official context page; that link does not imply the NBA or NIST endorses the analysis.</p>''')
print(f'Built 5 pages; results={len(joined)}, winner_direction={wins}, margin_mae={margin_mae:.2f}, total_mae={total_mae:.2f}, flags={len(issues)}')
